def top_k_frequent(nums, k):
    # Create a dictionary to store the frequency of each number
    freq = {}
    for num in nums:
        if num in freq:
            freq[num] += 1
        else:
            freq[num] = 1

    # Create a min heap from the frequency dictionary
    min_heap = []
    for num, freq in freq.items():
        heapq.heappush(min_heap, (-freq, num))

    # Extract the top k numbers from the heap
    top_k = []
    while k > 0:
        freq, num = heapq.heappop(min_heap)
        top_k.append(num)
        k -= 1

    return top_k

def max_Prime_Factors(n):
    factors = []
    while n % 2 == 0:
        factors.append(2)
        n = n // 2
    for i in range(3, int(n**0.5)+1, 2):
        while n % i == 0:
            factors.append(i)
            n = n // i
    if n > 2:
        factors.append(n)
    return max(factors)

