    for i in range(n):
        for j in range(n):
            if i == j:
                continue
            if matrix[i][j] == 0:
                for k in range(n):
                    if k != i and k != j:
                        if matrix[i][k] == 0:
                            matrix[i][k], matrix[k][j] = matrix[k][j], matrix[i][k]
                            break
    for i in range(n):
        for j in range(n):
            if i == j:
                continue
            if matrix[i][j] == 0:
                for k in range(n):
                    if k != i and k != j:
                        if matrix[k][j] == 0:
                            matrix[k][j], matrix[i][j] = matrix[i][j], matrix[k][j]
                            break
    for i in range(n):
        if 0 not in [matrix[j][i] for j in range(n)]:
            return True
    return False

