def max_path_sum(triangle, k, n):
    # Base case
    if n == 0:
        return 0
    if n == 1:
        return triangle[0][0]
    if n == 2:
        return max(triangle[0][0], triangle[1][0])

    # Recursive case
    max_sum = 0
    for i in range(1, n):
        max_sum = max(max_sum, triangle[i][0] + max_path_sum(triangle, i-1, i-1))
    return max_sum

