def longest_subseq_with_diff_one(arr, diff):
    n = len(arr)
    dp = [[0] * (diff + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        dp[i][0] = 1
    for i in range(1, n + 1):
        for j in range(1, diff + 1):
            if arr[i - 1] - j == 0:
                dp[i][j] = dp[i - 1][j]
            else:
                dp[i][j] = dp[i - 1][j] + dp[i - 1][j - 1]
    return dp[n][diff]

