    char_count = {}
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Create a list to store the characters with the minimum count
    min_count_chars = []
    min_count = 0
    for char, count in char_count.items():
        if count < min_count:
            min_count = count
            min_count_chars = [char]
