def find_peak(arr, n):
    left = 0
    right = n - 1
    while left < right:
        mid = (left + right) // 2
        if arr[mid] > arr[mid + 1]:
            right = mid
        else:
            left = mid + 1
    return arr[left]

def decimal_to_Octal(n):
    octal = ""
    while n > 0:
        octal = str(n % 8) + octal
        n = n // 8
    return octal

def max_product(arr, n):
    max_product = 0
    for i in range(n):
        for j in range(i+1, n):
            product = 1
            for k in range(i, j+1):
                product *= arr[k]
            if product > max_product:
                max_product = product
    return max_product

def max_profit(prices, k):
    if k == 0 or len(prices) == 0:
        return 0
    if k == 1:
        return max(prices)
    profit = 0
    for i in range(len(prices)):
        for j in range(i+1, len(prices)):
            profit = max(profit, prices[j] - prices[i])
    return profit

