def extract_symmetric(tuples):
    result = set()
    for i in range(len(tuples)):
        for j in range(i+1, len(tuples)):
            if tuples[i] == tuples[j]:
                result.add((tuples[i], tuples[j]))
    return result

def sum_gp(a, r, n):
    if n == 0:
        return 0
    elif n == 1:
        return a
    else:
        return a + sum_gp(a*r, r, n-1)

def binary_search(arr, x):
    low = 0
    high = len(arr) - 1
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == x:
            return mid
        elif arr[mid] < x:
            low = mid + 1
        else:
            high = mid - 1
    return -1

