def heap_queue_smallest(numbers, k):
    # Create a min-heap
    heap = []
    for num in numbers:
        heappush(heap, num)
    # Get the k smallest numbers
    smallest = []
    for _ in range(k):
        smallest.append(heappop(heap))
    return smallest

def gcd(a, b):
    if a == 0:
        return b
    if b == 0:
        return a
    if a == b:
        return a
    if a > b:
        return gcd(a - b, b)
    return gcd(a, b - a)

